package com.example.smartexpenseanalyzer.controller;
import jakarta.servlet.http.HttpSession; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin") public class AdminProfileController { private final com.example.smartexpenseanalyzer.service.ApiFacade app; public AdminProfileController(com.example.smartexpenseanalyzer.service.ApiFacade app){this.app=app;} @GetMapping("/overview") public Map<String,Object> overview(){return app.admin();} @GetMapping("/users") public List<Map<String,Object>> users(){return app.adminUsers();} @PutMapping("/users/{id}/role") public Map<String,Object> role(@PathVariable Long id,@RequestBody Map<String,String> body){return app.role(id,body);} @DeleteMapping("/users/{id}") public Map<String,String> delete(@PathVariable Long id,HttpSession session){return app.deleteUser(id,session);} }
